// src/invoice/invoice.controller.ts
import { Controller, Post, Body, Headers, Req } from '@nestjs/common';
import { InvoiceService } from './invoice.service';

@Controller('invoices')
export class InvoiceController {
  constructor(private readonly invoiceService: InvoiceService) {}

  @Post('import')
  async importInvoice(
    @Body() body: { xmlPayload: string },
    @Headers('x-tenant-id') tenantId: string,
  ) {
    // Parse the XML invoice data and store it
    const parsed = await this.invoiceService.parseAndStore(body.xmlPayload, tenantId);
    return { status: 'imported', invoiceId: parsed.id };
  }
}

