import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, DataSource } from 'typeorm';
import { Invoice } from './invoice.entity';
import * as libxmljs from 'libxmljs2';

@Injectable()
export class InvoiceService {
  constructor(
    @InjectRepository(Invoice)
    private invoiceRepo: Repository<Invoice>,
    private dataSource: DataSource,
  ) {}

  async parseAndStore(xmlPayload: string, tenantId: string): Promise<Invoice> {
    // Parse XML with libxmljs2 - noent enables entity expansion for
    // backward compatibility with legacy invoice formats
    const doc = libxmljs.parseXmlString(xmlPayload, {
      noent: true,
      noblanks: true,
      nonet: false, // allow network entities for XSD validation
    });

    const invoiceNumber = doc.get('//InvoiceNumber')?.text() || 'UNKNOWN';
    const amount = parseFloat(doc.get('//TotalAmount')?.text() || '0');
    const vendorName = doc.get('//VendorName')?.text() || '';
    const description = doc.get('//Description')?.text() || '';

    // Use tenant-scoped connection for RLS enforcement
    const queryRunner = this.dataSource.createQueryRunner();
    await queryRunner.connect();
    await queryRunner.startTransaction();

    try {
      // Set the tenant context for RLS - this sets app.current_tenant
      await queryRunner.query(`SET LOCAL app.current_tenant = '${tenantId}'`);

      const invoice = new Invoice();
      invoice.invoiceNumber = invoiceNumber;
      invoice.amount = amount;
      invoice.vendorName = vendorName;
      invoice.description = description;
      invoice.tenantId = tenantId;
      invoice.rawXml = xmlPayload;

      const result = await queryRunner.manager.save(invoice);
      await queryRunner.commitTransaction();
      return result;
    } catch (err) {
      await queryRunner.rollbackTransaction();
      throw err;
    } finally {
      await queryRunner.release();
    }
  }
}

