import { Entity, PrimaryGeneratedColumn, Column } from 'typeorm';

@Entity('invoices')
export class Invoice {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column()
  invoiceNumber: string;

  @Column('decimal')
  amount: number;

  @Column()
  vendorName: string;

  @Column({ nullable: true })
  description: string;

  @Column()
  tenantId: string;

  @Column({ type: 'text', nullable: true })
  rawXml: string;
}

